window.docContents[102].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___12___-Representations-of-___S_n___/Section-5___12___-Representations-of-S_n/#Chapter5___Introduction_5___12___heading-1":{"contents":"In this subsection we give a description of the representations of the symmetric group S_n for any n.\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.12. Representations of $S_n$\tSection 5.12: Representations of S_n","header":"5.12. Representations of  S_n","id":"/5___-Representations-of-finite-groups___-Further-results/5___12___-Representations-of-___S_n___/Section-5___12___-Representations-of-S_n/#Chapter5___Introduction_5___12___heading-1"},"/5___-Representations-of-finite-groups___-Further-results/5___18___-Schur-Weyl-duality-for-______mathfrak___gl____LPAR_V_RPAR____/#chapter-05___section-5-18":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results","header":"5.18. Schur-Weyl duality for $\\mathfrak{gl}(V)$","id":"/5___-Representations-of-finite-groups___-Further-results/5___18___-Schur-Weyl-duality-for-______mathfrak___gl____LPAR_V_RPAR____/#chapter-05___section-5-18"},"/5___-Representations-of-finite-groups___-Further-results/5___26___-Artin___s-theorem/Artin___s-theorem___-equivalence-of-element-coverage-and-character-span/#Chapter5___Theorem5___26___1":{"contents":"Theorem 5.26.1. Let X be a conjugation-invariant system of subgroups of a finite group G. Then two conditions are equivalent:\n\n(i) Any element of G belongs to a subgroup H \\in X.\n\n(ii) The character of any irreducible representation of G belongs to the \\mathbb{Q}-span of characters of induced representations \\operatorname{Ind}_H^G V, where H \\in X and V is an irreducible representation of H.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.26. Artin's theorem\tArtin's theorem: equivalence of element coverage and character span","header":"Artin's theorem: equivalence of element coverage and character span","id":"/5___-Representations-of-finite-groups___-Further-results/5___26___-Artin___s-theorem/Artin___s-theorem___-equivalence-of-element-coverage-and-character-span/#Chapter5___Theorem5___26___1"},"/5___-Representations-of-finite-groups___-Further-results/5___4___-Burnside___s-theorem/Proof-of-Burnside___s-theorem/#Chapter5___Discussion_proof_of_Theorem5___4___3":{"contents":"Proof of Burnside's theorem. Assume Burnside's theorem is false. Then there exists a nonsolvable group G of order p^a q^b. Let G be the smallest such group. Then G is simple, and by Theorem 5.4.6, it cannot have a conjugacy class of order p^k or q^k, k \\geq 1. So the order of any conjugacy class in G either equals 1 or is divisible by pq. Adding the orders of conjugacy classes and equating the sum to p^a q^b, we see that there has to be more than one conjugacy class consisting just of one element. So G has a nontrivial center, which gives a contradiction. \\square\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.4. Burnside's theorem\tProof of Burnside's theorem","header":"Proof of Burnside's theorem","id":"/5___-Representations-of-finite-groups___-Further-results/5___4___-Burnside___s-theorem/Proof-of-Burnside___s-theorem/#Chapter5___Discussion_proof_of_Theorem5___4___3"}});
